      fnSource: parsed.fnSource!,
      argsJson: parsed.argsJson!,
      context: context?.call(),
    );
    return jsonEncode(jobId);
  } catch (e) {
    return jsonEncode({'__jsError': 'runAsync dispatch failed: $e'});
  }
}

/// Validates the JS-side `runAsync(fn, args)` arguments.
