void _registerPoolDispatchTests(_Fixture f) {
  test('dispatch/wait roundtrip without a JS engine on the caller', () {
    final jobId = f.pool.dispatch(
      fnSource: 'function(args) { return args.x + 1; }',
      argsJson: '{"x":41}',
      scriptDirectory: f.tmp.path,
      params: const {},
    );
