/// The `require` base directory of [scriptPath] (JS `scriptDirOf` parity).
String jsDirectoryOf(String scriptPath) {
  if (!scriptPath.contains('/')) return '';
  return scriptPath.substring(0, scriptPath.lastIndexOf('/'));
}

